import{f as n,o as a,c as s,a6 as o}from"./chunks/framework.Dd1qhYRL.js";const h=JSON.parse('{"title":"Discovering command help","description":"","frontmatter":{},"headers":[],"relativePath":"cli/help.md","filePath":"cli/help.md"}'),t={name:"cli/help.md"};function l(p,e,c,d,i,r){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="discovering-command-help" tabindex="-1">Discovering command help <a class="header-anchor" href="#discovering-command-help" aria-label="Permalink to “Discovering command help”">​</a></h1><p>Append <code>--help</code> or <code>-h</code> to any command to see its usage, flags, and examples.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ noorm run inspect --help</span></span>
<span class="line"><span>Inspect template context for a .sql.tmpl file (noorm run inspect)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>USAGE noorm run inspect [OPTIONS] &lt;PATH&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ARGUMENTS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PATH    Path to the .sql.tmpl file (Required)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OPTIONS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  -c, --config=&lt;config&gt;    Use specific configuration</span></span>
<span class="line"><span>                 --json    Output JSON               </span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>EXAMPLES</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  noorm run inspect db/sql/users/001_create.sql.tmpl</span></span>
<span class="line"><span>  noorm run inspect db/sql/core/05_Cron/Crons.sql.tmpl --json</span></span></code></pre></div><p>The same flag works at every depth: <code>noorm --help</code>, <code>noorm db --help</code>, <code>noorm db create --help</code>, <code>noorm change ff --help</code>. A parent command lists its subcommands. A leaf command lists its flags and an <code>EXAMPLES</code> block when its author wrote one.</p><h2 id="what-if-i-type-noorm-help-command" tabindex="-1">What if I type <code>noorm help &lt;command&gt;</code>? <a class="header-anchor" href="#what-if-i-type-noorm-help-command" aria-label="Permalink to “What if I type noorm help &lt;command&gt;?”">​</a></h2><p>noorm has no <code>help</code> subcommand. citty renders help per command, so one source serves every command and no second copy can drift.</p><table tabindex="0"><thead><tr><th>Input</th><th>Result</th></tr></thead><tbody><tr><td><code>noorm &lt;command&gt; --help</code>, <code>-h</code></td><td>Usage, flags, examples; exit 0</td></tr><tr><td><code>noorm --help</code></td><td>Command list; exit 0</td></tr><tr><td><code>noorm</code></td><td>Command list, then <code>No command specified.</code>; exit 1</td></tr><tr><td><code>noorm help db create</code></td><td>Command list, then <code>Unknown command help</code>; exit 1</td></tr><tr><td><code>noorm --version</code>, <code>noorm -v</code></td><td>Version only, when it is the sole argument</td></tr></tbody></table><p>For shell completion, run <code>noorm complete &lt;shell&gt;</code> and source the script it prints. <a href="/cli/flags.html">Flag placement</a> explains where <code>--help</code> and the other flags may go.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/cli/flags.html">CLI flag conventions</a></li><li><a href="/headless.html">CLI reference</a></li></ul>`,10)])])}const f=n(t,[["render",l]]);export{h as __pageData,f as default};
